data.pageStyle:
/* ========================================================================
   AmazingLife checkout theme — matches amazinglife.com
   Deep forest-green page · floating rounded cards · lime→green accents
   ======================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap');

:root {
  --al-forest:    #001E17;  /* darkest green (page + header)   */
  --al-forest-2:  #002F24;  /* button text / deep accents      */
  --al-green:     #54EB77;  /* bright brand green              */
  --al-lime:      #DCFF64;  /* lime highlight                  */
  --al-grad: linear-gradient(101deg,#DCFF64 0%,#98F56E 45%,#76F072 72%,#54EB77 100%);
  --al-card-radius: 24px;
}

/* ---- Page background: green instead of white/grey -------------------- */
body,
.wrapper,
.limio-page-right_nav {
  background: radial-gradient(1100px 600px at 12% -10%, #0a3d2c 0%, var(--al-forest) 55%) fixed !important;
}
.wrapper main,
#limio-view-layout { background: transparent; }

/* Typeface across the checkout */
.limio-page-right_nav,
.limio-page-right_nav input,
.limio-page-right_nav select,
.limio-page-right_nav button,
.limio-page-right_nav label { font-family: 'Poppins', system-ui, sans-serif; }

/* ---- Header bar: deep green, logo white ------------------------------ */
.limio-header,
.limio-header .limio-component,
.limio-header #nav-header-limio,
.limio-header .navbar {
  background: var(--al-forest) !important;
  border: none !important;
  box-shadow: none !important;
}
.limio-header .navbar { padding: 6px 24px; }
.header-logo { filter: brightness(0) invert(1); }  /* remove if logo is already light */

/* ---- Layout: two floating cards, wider cart, equal margins ----------- */
.limio-body-right_nav {
  display: flex !important;
  max-width: 1180px;
  margin: 0 auto;
  padding: 44px 24px 72px;
  gap: 40px;
  align-items: flex-start;
}

/* shared card shell — the white/green boxes */
.limio-content,
.limio-side-nav {
  border-radius: var(--al-card-radius);
  padding: 40px !important;
  box-shadow: 0 24px 60px -24px rgba(0,0,0,.55);
}
.limio-content  { background: #ffffff !important; flex: 1 1 auto; min-width: 0; }      /* form */
.limio-side-nav { background: #F3FBF4 !important; flex: 0 0 440px; max-width: 440px; } /* cart */

/* Headings in brand green */
.limio-content h1, .limio-content h2, .limio-content h3,
.limio-side-nav h1, .limio-side-nav h2, .limio-side-nav h3 {
  color: var(--al-forest) !important;
  font-weight: 700;
  letter-spacing: -.02em;
}

/* Hairline dividers → soft green-grey */
.tw-bg-border { background-color: #dfeee4 !important; border-color: #dfeee4 !important; }

/* ---- Inputs: rounder, green focus ------------------------------------ */
.limio-content input,
.limio-content select {
  border-radius: 10px !important;
  border-color: #d6e2da !important;
}
.limio-content input:focus,
.limio-content select:focus,
.limio-content input:focus-visible,
.limio-content select:focus-visible {
  border-color: var(--al-green) !important;
  box-shadow: 0 0 0 3px rgba(84,235,119,.30) !important;
  outline: none !important;
}

/* Radios / checkboxes pick up brand green */
.limio-content input[type="radio"],
.limio-content input[type="checkbox"] { accent-color: var(--al-forest-2) !important; }

/* Payment tiles: selected = green border + light green fill, rounded */
.payment-group label { border-radius: 12px !important; }
.payment-group label:has(input:checked) {
  border-color: var(--al-green) !important;
  background: #EFFBF1 !important;
}

/* ---- Submit button: lime→green gradient pill ------------------------- */
.limio-content form button[type="submit"] {
  background: var(--al-grad) !important;
  color: var(--al-forest-2) !important;
  font-weight: 600;
  border: none !important;
  border-radius: 999px !important;
  padding: 14px 28px !important;
  box-shadow: 0 10px 24px -8px rgba(84,235,119,.6);
  transition: transform .15s ease, box-shadow .15s ease, filter .15s ease;
}
.limio-content form button[type="submit"]:hover {
  filter: brightness(1.04);
  transform: translateY(-1px);
  box-shadow: 0 14px 30px -8px rgba(84,235,119,.7);
}

/* ---- Cart: prices/totals in deep green ------------------------------- */
.limio-side-nav [data-testid="item-price"],
.limio-side-nav [id^="cart-total-label"],
.limio-side-nav [aria-labelledby^="cart-total-label"],
.limio-side-nav [aria-labelledby^="cart-subtotal-label"] {
  color: var(--al-forest) !important;
}

/* ---- Mobile: stack the cards ----------------------------------------- */
@media (max-width: 820px) {
  .limio-body-right_nav { flex-direction: column; }
  .limio-content,
  .limio-side-nav { width: 100%; flex: 1 1 auto; max-width: none; padding: 28px !important; }
}
